const suffix = Date.now();
pm.collectionVariables.set('crudEmail', `casey.nguyen+${suffix}@partner.example.com`);
pm.collectionVariables.set('crudPartnerReferenceId', `crud-postman-${suffix}`);

pm.test('POST /applications — should create a CRUD test application', function () {
  pm.response.to.have.status(201);
});
const body = pm.response.json();
pm.test('Created CRUD application has submitted state and generated ID', function () {
  pm.expect(body.data.id).to.be.a('string');
  pm.expect(body.data.status).to.eql('submitted');
  pm.expect(body.data.applicant.email).to.eql(pm.collectionVariables.get('crudEmail'));
});
pm.collectionVariables.set('crudApplicationId', body.data.id);

pm.test('GET /applications/:id — should retrieve CRUD test application', function () {
  pm.response.to.have.status(200);
});
const body = pm.response.json();
pm.test('Retrieved CRUD application matches captured ID', function () {
  pm.expect(body.data.id).to.eql(pm.collectionVariables.get('crudApplicationId'));
  pm.expect(body.data.status).to.eql('submitted');
});

pm.test('PATCH /applications/:id/status — should update CRUD test application', function () {
  pm.response.to.have.status(200);
});
const body = pm.response.json();
pm.test('CRUD application state changes to in_review', function () {
  pm.expect(body.data.id).to.eql(pm.collectionVariables.get('crudApplicationId'));
  pm.expect(body.data.status).to.eql('in_review');
  pm.expect(body.data.updatedAt).to.be.a('string');
});

pm.test('DELETE /applications/:id — should cancel CRUD test application', function () {
  pm.response.to.have.status(200);
});
const body = pm.response.json();
pm.test('Cancelled application remains in response with cancelled status', function () {
  pm.expect(body.data.id).to.eql(pm.collectionVariables.get('crudApplicationId'));
  pm.expect(body.data.status).to.eql('cancelled');
  pm.expect(body.data.decisionReason).to.include('cancelled');
});
pm.test('Cancel response includes correlation metadata', function () {
  pm.expect(body.meta.correlationId).to.be.a('string');
});

pm.test('GET /applications — should return 401 for invalid API key', function () {
  pm.response.to.have.status(401);
});
const body = pm.response.json();
pm.test('Invalid auth response has error code and correlation ID', function () {
  pm.expect(body.error.code).to.eql('UNAUTHORIZED');
  pm.expect(body.error.message).to.be.a('string');
  pm.expect(body.error.correlationId).to.be.a('string');
});

pm.test('POST /applications — should return 400 for missing required fields', function () {
  pm.response.to.have.status(400);
});
const body = pm.response.json();
pm.test('Validation error response uses standard error envelope', function () {
  pm.expect(body.error.code).to.eql('VALIDATION_ERROR');
  pm.expect(body.error.message).to.include('Missing required fields');
  pm.expect(body.error.correlationId).to.be.a('string');
});

pm.test('GET /applications/:id — should return 404 for unknown ID', function () {
  pm.response.to.have.status(404);
});
const body = pm.response.json();
pm.test('Not-found response identifies missing application', function () {
  pm.expect(body.error.code).to.eql('APPLICATION_NOT_FOUND');
  pm.expect(body.error.message).to.include(pm.collectionVariables.get('unknownApplicationId'));
  pm.expect(body.error.correlationId).to.be.a('string');
});

pm.test('PATCH /applications/:id/status — should return 409 for invalid transition', function () {
  pm.response.to.have.status(409);
});
const body = pm.response.json();
pm.test('Invalid transition response uses business error code', function () {
  pm.expect(body.error.code).to.eql('INVALID_STATUS_TRANSITION');
  pm.expect(body.error.message).to.include('approved');
  pm.expect(body.error.correlationId).to.be.a('string');
});
